// CSD_RATIONALE_BEGIN
// Math word problem CSD. The strategy generates step-by-step reasoning freely,
// then wraps symbolic expressions and the final answer in << >> delimiters using
// hard parser control inside spans. The outer loop alternates between:
//   1. Unconstrained free text (reasoning steps, prose)
//   2. Constrained spans (symbolic expressions, final answer) triggered by "<<"
// Inside constrained spans, AdaptiveConstrainedStep is used with group boosts
// for narrow parser states. CloseSpanIfComplete handles closing each span.
// Multiple spans may appear (one per intermediate expression and one for the
// final answer). The strategy tracks insideConstrainedOut and currentConstrainedOut
// for parser validity, and steps for the budget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Outside-span branch: flips insideConstrainedOut true only on next == "<<",
//     at which point currentConstrainedOut := [] which is valid by precondition
//     parser.IsValidPrefix([]). All other outside-span paths leave the
//     implication vacuously true (insideConstrainedOut == false).
//   CloseSpanIfComplete branch: when closed == true, insideConstrainedOut
//     becomes false (implication vacuous, currentConstrainedOut == []). When
//     closed == false, state is unchanged so invariant holds by IH.
//   AdaptiveConstrainedStep branch: the helper returns EOS or a token t such
//     that parser.IsValidPrefix(currentConstrainedOut + [t]) holds.
//     AppendConstrainedToken preserves both parser validity and the length bound
//     |currentConstrainedOut| <= |generated|.
// progress:
//   Every branch increments steps by exactly 1. The outside-span branch appends
//     at most one token (next), so |generated| grows by at most 1.
//   The CloseSpanIfComplete branch appends at most one token (">>" delimiter),
//     so |generated| grows by at most 1. Cost is 1 in both the closed and
//     no-op paths.
//   The constrained step branch appends at most one token (next), so |generated|
//     grows by at most 1.
//   In all cases |generated| <= |generatedPrefix| + steps is preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math problem step by step. Wrap each symbolic expression and the final numeric answer inside << >> delimiters. For example: The total is <<3 + 4 = 7>>. The answer is <<42>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Math word problem CSD with improved span management.
// Key insight from failures:
// 1. The model generates LaTeX-style expressions with {}, ** etc. inside spans - we need
//    the parser to reject these and force valid mathematical expressions.
// 2. Many examples hit max steps without closing spans - we need to be more aggressive
//    about closing spans once we have valid content.
// 3. The free-text phase often produces reasoning without ever emitting "<<" - we need
//    to force a final answer span near the end of the budget.
//
// Strategy:
// Phase 1: Generate unconstrained reasoning text with a budget cap (~70% of maxSteps).
//   During this phase, if the model naturally emits "<<", enter constrained mode.
// Phase 2: If no span was opened and we're near budget, force open a "<<" span and
//   use CloseSpanWithinBudget to reliably close it within the remaining budget.
// Inside spans: use SafeTemperatureConstrainedStep (low temperature for precision)
//   combined with CloseSpanIfComplete to close as soon as parser accepts.
// The guidance explicitly forbids LaTeX and curly braces, instructing the model to
//   produce plain arithmetic expressions only inside << >>.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Phase 1 (unconstrained loop): insideConstrainedOut flips to true only when
//     next == "<<", at which point currentConstrainedOut := [] which satisfies
//     parser.IsValidPrefix([]) by precondition. The implication is vacuous while
//     insideConstrainedOut == false.
//   CloseSpanIfComplete branch: when closed == true, insideConstrainedOut becomes
//     false making implication vacuous; when closed == false, state unchanged so
//     invariant holds by inductive hypothesis.
//   SafeTemperatureConstrainedStep: returns EOS or a parser-valid next token.
//     AppendConstrainedToken preserves parser.IsValidPrefix(currentConstrainedOut).
//   OpenConstrainedSpan (forced): sets currentConstrainedOut := [] which is valid.
//   CloseSpanWithinBudget: postcondition guarantees insideOut ==>
//     parser.IsValidPrefix(currentOut), so invariant preserved.
// progress:
//   Phase 1 unconstrained loop: each iteration increments steps by 1 and appends
//     at most one token to generated, so |generated| <= |generatedPrefix| + steps.
//   CloseSpanIfComplete: costs 1 step, appends at most one token (">>" delimiter).
//   SafeTemperatureConstrainedStep + AppendConstrainedToken: costs 1 step total,
//     appends at most one token.
//   OpenConstrainedSpan: costs 1 step, appends exactly "<<".
//   CloseSpanWithinBudget with budget = remainBudget: by postcondition
//     |generatedOut| <= |generated| + remainBudget. We set steps := maxSteps
//     so total steps = maxSteps and |generated| <= |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math problem step by step. At the very end, write 'The answer is <<EXPR>>' where EXPR is a plain arithmetic expression using only numbers, variable names, +, -, *, /, //, %, (, ), and no LaTeX, no curly braces, no backslashes. Example: The answer is <<n * p * (1 + r / 100)>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
// Use 75% of budget for free reasoning, reserve 25% for forced constrained span
var freeBudget: nat := (maxSteps * 3) / 4;
if freeBudget == 0 && maxSteps > 0 {
  freeBudget := 1;
}

// Phase 1: Unconstrained reasoning with natural span detection
while steps < freeBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Handle constrained spans (either naturally opened or forced)
// Process any span that was naturally opened during Phase 1
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
