  if closed {
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeTemperatureConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, 0.8, eosToken);
    if next == eosToken {
