//   CloseSpanWithinBudget with budget = remainBudget: postcondition gives
//   |generatedOut| <= |generated| + remainBudget; setting steps := maxSteps keeps
//   |generated| <= |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. End with: The answer is <<EXPR>> where EXPR uses only variable names, numbers, +, -, *, /, //, %, (, ). No LaTeX, no {}, no backslashes, no **.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var freeBudget: nat := maxSteps / 3;
if freeBudget == 0 && maxSteps > 0 {
