currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. Write the final answer as: The answer is <<EXPR>> where EXPR uses only variable names, numbers, +, -, *, /, //, %, (, ). No LaTeX, no {}, no **, no backslashes. Keep the expression short and concise.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Track whether we've already produced a complete valid span
var hasCompletedSpan: bool := false;

// Phase 1: Unconstrained reasoning until "<<" appears or 85% budget used
var phase1Budget: nat := (maxSteps * 85) / 100;
if phase1Budget == 0 && maxSteps > 0 {
  phase1Budget := 1;
}

while steps < phase1Budget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Budget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := eg;
      insideConstrainedOut := ei;
      currentConstrainedOut := ec;
    }
  }
}

// Phase 2: If we entered a constrained span, use CloseSpanWithinBudget with small budget
// to prevent runaway repetition
if insideConstrainedOut && steps < maxSteps {
  var spanBudget: nat := 40;
  var remainAfterPhase1 := maxSteps - steps;
  if spanBudget > remainAfterPhase1 {
    spanBudget := remainAfterPhase1;
  }
  if spanBudget > 0 {
    var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget);
    generated := wg;
    insideConstrainedOut := wi;
    currentConstrainedOut := wc;
    steps := steps + spanBudget;
    if !insideConstrainedOut {
      hasCompletedSpan := true;
    }
  }
}

// Phase 3: After span closed, continue unconstrained briefly but stop if another "<<" would open
// We only continue if we haven't hit budget and the span was properly closed
while steps < phase1Budget && !insideConstrainedOut && !hasCompletedSpan == false
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Budget - steps
{
  steps := steps + (phase1Budget - steps);
}

// Phase 4: If no complete span produced, force open a new span and use CloseSpanWithinBudget
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var openCount := CSDHelpers.CountTokenOccurrences(generated, "<<");
  var closeCount := CSDHelpers.CountTokenOccurrences(generated, ">>");
  if openCount <= closeCount {
    // No unmatched open span, and no complete span yet - force one
    if steps + 2 <= maxSteps {
      var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
      generated := fg;
      insideConstrainedOut := fi;
      currentConstrainedOut := fc;
      steps := steps + 1;

      var remainBudget := maxSteps - steps;
      if remainBudget > 40 {
        remainBudget := 40;
      }
      if remainBudget > 0 {
        var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainBudget);
        generated := wg;
        insideConstrainedOut := wi;
        currentConstrainedOut := wc;
        steps := steps + remainBudget;
      }
    }
  }
}

// If still inside a constrained span (CloseSpanWithinBudget couldn't close), handle remaining budget
if insideConstrainedOut && steps < maxSteps {
  var finalBudget := maxSteps - steps;
  if finalBudget > 0 {
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + finalBudget;
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Deep analysis of failures:
// 1. The core problem is that the model generates ~270 tokens of LaTeX-style reasoning,
//    then emits "<<" at the end, and the constrained content becomes repetitive garbage.
// 2. "final_span_unclosed" (8 examples): Model emits "<<" then immediately EOS or dead-end.
//    This happens because the model is at token budget when it finally emits "<<".
// 3. "final_span_invalid" (1 example): Repetition loops inside the span.
// 4. The previous attempt (8) used CloseSpanWithinBudget with 40-token budget which helped
//    syntax (81.6%) but accuracy was still very low (8.2%) because the constrained content
//    was wrong (the model was mid-sentence when "<<" was emitted).
//
// Root cause of unclosed spans: The model emits "<<" very late (avg 272 tokens in).
// Our Phase 2 CloseSpanWithinBudget with spanBudget=40 gives enough budget, but when
// the model emits "<<" mid-expression (like "...expression becomes {frac_1 * {frac_2} * $n$.
// The final answer is <<"), the constrained content starts with garbage.
//
// Key observation from rollouts: When the model writes "The final answer is <<EXPR>>" naturally,
// it produces correct syntax. The problem is:
// (a) Sometimes it emits "<<" mid-sentence by accident (the "<<" in "<<{frac_1..." case)
// (b) Sometimes the CloseSpanWithinBudget budget is insufficient
// (c) After CloseSpanWithinBudget, the model opens ANOTHER "<<" span which creates 
//     the "<<...>><<" pattern seen in multiple examples
//
// The "<<...>><<" problem: After CloseSpanWithinBudget closes the first span, the model
// continues generating and naturally emits another "<<". Our Phase 3 loop was broken
// (it had `!hasCompletedSpan == false` which evaluates to `!false == true` always, so
// the loop never actually prevented a second span). This led to DOUBLE spans.
//
// FIX STRATEGY:
// 1. Let the model generate FREELY for most of the budget (up to 800 tokens out of 900)
//    watching for "<<". Use UnconstrainedChunk to efficiently batch free generation.
// 2. When "<<" is detected naturally, immediately use CloseSpanWithinBudget with budget=50
//    to close it cleanly.
// 3. After the span closes, use ManagedStep or UnconstrainedStep for at most 10 more tokens,
//    but STOP if another "<<" appears (to prevent double spans).
// 4. If no span detected within first 800 tokens, force open one and use CloseSpanWithinBudget
//    with remaining budget.
// 5. If at any point we're stuck inside a constrained span at end of budget, use remaining
//    budget to close it.
//
// The key fix for the "<<...>><<" problem: After a span is closed, continue unconstrained 
// but if another "<<" is emitted, DON'T enter constrained mode - just append it as text
// since we already have a complete answer. Actually we can't control that - if "<<" appears
// in generated text it becomes a delimiter. Better: just stop after first complete span.
//
// REVISED APPROACH: After the first span is successfully closed, stop generating entirely.
// This prevents the second "<<" problem entirely. The model will have its answer in the span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Phase 1 (UnconstrainedChunk loop): insideConstrainedOut remains false until stoppedOnOpenSpan.
//     When stoppedOnOpenSpan, generated already ends with "<<" and we call EnterObservedConstrainedSpan
//     which sets currentConstrainedOut := [] (valid by precondition parser.IsValidPrefix([])).
//     While insideConstrainedOut is false, the implication is vacuous.
//   CloseSpanWithinBudget (Phase 2): postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut), preserving invariant.
//     When closed (!insideConstrainedOut), implication is vacuous.
//   Phase 3 (post-close unconstrained, limited steps): insideConstrainedOut is false,
//     implication is vacuous. We break if another "<<" appears and enter span state with
//     currentConstrainedOut := [] (valid). Then CloseSpanWithinBudget again preserves invariant.
//   Phase 4 (forced open): OpenConstrainedSpan sets currentConstrainedOut := [] (valid).
//     CloseSpanWithinBudget postcondition preserves invariant.
//   Phase 5 (final close if still open): CloseSpanWithinBudget postcondition preserves invariant.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk with maxChunkTokens=chunkSize returns stepsUsed >= 1 and
//     |generatedOut| <= |generated_before| + stepsUsed. We add stepsUsed to steps.
//     Since stepsUsed <= chunkSize and we check steps + chunkSize <= maxSteps before calling,
//     we have steps + stepsUsed <= maxSteps after the call, and
//     |generated| <= |generatedPrefix| + steps throughout.
//   CloseSpanWithinBudget with budget b: postcondition gives |generatedOut| <= |generated| + b.
//     We add exactly b to steps. So |generated| <= |generatedPrefix| + steps preserved.
//   Phase 3 unconstrained: each UnconstrainedStep increments steps by 1 and appends at most 1 token.
//   Phase 4 OpenConstrainedSpan: costs 1 step, appends 1 token ("<<"). steps += 1.
//   All phases maintain |generated| <= |generatedPrefix| + steps <= |generatedPrefix| + maxSteps.
